#!/usr/bin/env node
// Convert a pack's `pack.mjs` manifest into the `pack.json` the loader prefers. The
// module is evaluated and its default export written back as data, key order kept, so
// the JSON loads to exactly what the module did. A `relevanceDetector` pattern becomes
// its source string, or `{ source, flags }` where it carries a flag, and the retired
// fingerprint fields are dropped. A value JSON cannot carry - a function, a module that
// imports a sibling - leaves the manifest a module, which the loader still reads, and
// says why. Comments do not survive.
//
// Two callers. The `pack-json-manifests` migration record runs this against a member's
// OWN local packs on its nightly update, through the registry's io, evaluating each
// manifest from its text; and the CLI below converts a checkout by hand, evaluating each
// file where it sits, so a manifest importing a sibling still resolves:
//
//   node engine/migrations/manifests-to-json.mjs [--root <repo>] [<pack dir>…]

import { existsSync, readFileSync, writeFileSync, rmSync, readdirSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { MANIFEST_JSON, MANIFEST_MODULE } from '../pack_loader/pack-conventions.mjs';
import { RETIRED_FINGERPRINT_FIELDS } from '../pack_loader/pack-schema.mjs';
import { LOCAL_PACK_ROOT } from './task-declarations-to-json.mjs';

const isPlainObject = (v) => v !== null && typeof v === 'object' && Object.getPrototypeOf(v) === Object.prototype;

function toData(value, at) {
  if (value === null || ['string', 'number', 'boolean'].includes(typeof value)) return value;
  if (value instanceof RegExp) return value.flags ? { source: value.source, flags: value.flags } : value.source;
  if (typeof value === 'function') throw new Error(`${at} is a function`);
  if (Array.isArray(value)) return value.map((v, i) => toData(v, `${at}[${i}]`));
  if (!isPlainObject(value)) throw new Error(`${at} is not plain data`);
  const out = {};
  for (const [k, v] of Object.entries(value)) if (v !== undefined) out[k] = toData(v, at ? `${at}.${k}` : k);
  return out;
}

// `{ json }` for a manifest that converts, `{ why }` for one that stays a module. `url`
// is where the module is evaluated from; its text alone by default.
export async function manifestToJson(source, { url = `data:text/javascript;base64,${Buffer.from(source).toString('base64')}` } = {}) {
  let mod;
  try {
    mod = (await import(url)).default;
  } catch (e) {
    return { why: `it does not evaluate on its own: ${e.message}` };
  }
  if (!isPlainObject(mod)) return { why: 'its default export is not an object' };
  const kept = Object.fromEntries(Object.entries(mod).filter(([k]) => !RETIRED_FINGERPRINT_FIELDS.includes(k)));
  try {
    return { json: `${JSON.stringify(toData(kept, ''), null, 2)}\n` };
  } catch (e) {
    return { why: e.message };
  }
}

// Every pack directory under `root` still carrying only a module manifest, converted
// through `io` (read, write, listDir, remove). One line per pack touched.
export async function manifestsToJson(root, io) {
  const done = [];
  for (const name of (io.listDir(root) ?? []).sort()) {
    const dir = `${root}/${name}`;
    const module = `${dir}/${MANIFEST_MODULE}`;
    if (!io.exists(module) || io.exists(`${dir}/${MANIFEST_JSON}`)) continue;
    const { json, why } = await manifestToJson(await io.read(module));
    if (!json) { done.push(`${module}: kept as ${MANIFEST_MODULE} - ${why}`); continue; }
    await io.write(`${dir}/${MANIFEST_JSON}`, json);
    await io.remove(module);
    done.push(`${module} -> ${MANIFEST_JSON}`);
  }
  return done;
}

async function main(argv) {
  const at = argv.indexOf('--root');
  const root = resolve(at === -1 ? process.cwd() : argv[at + 1]);
  const named = argv.filter((a, i) => a !== '--root' && argv[i - 1] !== '--root');
  const localRoot = join(root, LOCAL_PACK_ROOT);
  const dirs = named.length
    ? named.map((d) => resolve(root, d))
    : (existsSync(localRoot) ? readdirSync(localRoot).map((n) => join(localRoot, n)) : []);
  for (const dir of dirs) {
    const module = join(dir, MANIFEST_MODULE);
    if (!existsSync(module) || existsSync(join(dir, MANIFEST_JSON))) continue;
    const { json, why } = await manifestToJson(readFileSync(module, 'utf8'), { url: pathToFileURL(module).href });
    // A manifest that stays a module is still read, so it is reported, not a failure.
    if (!json) { console.log(`${module}: kept as ${MANIFEST_MODULE} - ${why}`); continue; }
    writeFileSync(join(dir, MANIFEST_JSON), json);
    rmSync(module);
    console.log(`${module} -> ${MANIFEST_JSON}`);
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main(process.argv.slice(2)).catch((e) => { console.error(e.message); process.exitCode = 1; });
}
import { sep } from 'node:path';
import { finding } from '../../../engine/checks/helpers/findings.mjs';
import { LOCAL_PACKS_SUBDIR } from '../../../engine/pack_loader/pack-registry.mjs';
import { PROVENANCE_DIR } from '../../../engine/pack_loader/pack-conventions.mjs';

// The machine backstop for the growth-dedup task doc's rule: a dedup edit only ever REMOVES
// portable text. The routine has instead reworded partially-covered items —
// leading with a "this rule is portable (canon)" meta-line and re-stating the
// now-canon rule (and which pack owns it) inside the local pack — which grows
// the entry and duplicates canon prose, the inverse of dedup. Two independent
// signals catch that:
//
//  (1) Canon-restatement fingerprint. An ADDED local-pack prose line that says
//      a rule "is portable (canon)", that a "pack owns" a rule, or that the
//      canon "owns" it, is re-importing the canon into the local pack. This is
//      a corruption on any branch, dedup-labeled or not, so it is unscoped. The
//      legitimate delegation convention ("(canon): here <residue>") names the
//      canon without any of these phrasings, so it is not matched.
//
//  (2) A dedup run must SHRINK the pack it prunes. Scoped to a run whose commits
//      announce a dedup (extract legitimately GROWS a pack, so the shrink
//      invariant can't be unscoped): a modified local-pack prose file that ends
//      up longer than its base — in lines, or in characters once a re-wrap has
//      hidden the growth from the line count — grew instead of pruning. This is
//      the only measure of shrink-only there is: the task's auto-merge policy
//      scopes a prune to the local-pack tree and judges nothing about its shape.
//
//      A commit message saying "dedup" is not enough on its own — a change that
//      FIXES the dedup routine says "dedup" too, and it edits the canon while
//      touching a local pack, which reads as a corrupt prune. So the shrink
//      invariant also requires the branch to be CONFINED to the local-pack
//      surface, which a real run always is: the routine's own first prohibition
//      is that it never edits the canon it prunes against. A branch reaching
//      outside local packs is canon work that merely mentions dedup.
//
//      A pack's provenance files are exempt from the shrink measure, never from
//      the fingerprint: a remove prune must append a `retired` entry to the
//      element's append-only decision log, so that file always grows.
//
// git emits '/'-separated paths, so the platform-joined constant is normalized.
const LOCAL_ROOT = `${LOCAL_PACKS_SUBDIR.split(sep).join('/')}/`;

const isLocalPackProse = (file) => file.endsWith('.md') && file.startsWith(LOCAL_ROOT);
const isProvenance = (file) => file.slice(LOCAL_ROOT.length).split('/')[1] === PROVENANCE_DIR;

const RESTATES_CANON = /\b(?:is|are) portable\s*\(canon\)|\bpack owns\b|\bcanon (?:now )?owns\b|\bowned by (?:the )?canon\b/i;
const DEDUP_RUN = /\bdedup\b|\bcanon now (?:covers|owns)\b/i;

const rule = {
  id: 'dedup-prune-integrity',
  on_fail: 'block',
  scope: 'work',
  doc: 'packs/claudinite-growth/skills/growth-dedup/SKILL.md',
  description: 'A dedup edit only removes portable text — it never grows a local pack or re-imports a canon rule into it',
  why: 'the growth-dedup routine has reworded partially-covered items instead of stripping them — restating the canon rule inside the local pack, the inverse of dedup — and every dedup edit must shrink the pack, not grow it',

  run(work) {
    if (work.onDefaultBranch()) return [];
    const prose = work.changedFiles.filter(isLocalPackProse);
    if (!prose.length) return [];
    const findings = [];

    // (1) Canon-restatement fingerprint — unscoped: no legitimate edit re-imports
    // a canon rule into a local pack.
    for (const { file, line, text } of work.addedLines(prose)) {
      if (RESTATES_CANON.test(text)) {
        findings.push(finding(rule, {
          file,
          line,
          what: `local-pack prose re-imports a canon rule: "${text.trim().slice(0, 80)}"`,
          fix: 'delegate the portable rule to the canon and keep only this project\'s residue — never restate the canon rule, its fix, or which pack owns it (use the pack\'s "(canon): here …" convention)',
        }));
      }
    }

    // (2) A dedup run must shrink the pack it prunes, never grow it.
    const isDedupRun = work.commits.some((m) => DEDUP_RUN.test(m)) &&
      work.changedFiles.every((f) => f.startsWith(LOCAL_ROOT));
    if (isDedupRun) {
      for (const file of prose.filter((f) => !isProvenance(f))) {
        const base = work.readBase(file);
        const head = work.read(file);
        // A file absent at base (new pack) or gone at head (whole-file prune)
        // did not grow — only a modified-in-place file can.
        if (base === null || head === null) continue;
        // Lines AND characters, because re-wrapping trades one for the other:
        // a strip that pulls text up across line boundaries can shrink the line
        // count while the entry itself grows.
        const baseLines = base.split('\n').length;
        const headLines = head.split('\n').length;
        const grew = headLines > baseLines ? `from ${baseLines} to ${headLines} lines`
          : head.length > base.length ? `from ${base.length} to ${head.length} characters`
            : null;
        if (grew) {
          findings.push(finding(rule, {
            file,
            what: `a dedup run grew ${file} ${grew} — a prune/strip removes duplicated text, it never grows the pack`,
            fix: 'strip each covered item down to its project residue (a deletion that shrinks the entry); if you are keeping an item, leave it unchanged rather than rewording it',
          }));
        }
      }
    }

    return findings;
  },
};

export default rule;

